function normalize(name: string): string {
  return name
    .toLowerCase()
    .replace(/[''`.]/g, '')
    .replace(/[-]/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/\b(jr|sr|ii|iii|iv)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

export function getRefValue(normalizedName: string): number | undefined {
  return REF_DATA[normalizedName];
}

export function buildRefMap(playerDB: Record<string, { full_name?: string; first_name?: string; last_name?: string }>): Record<string, number> {
  const map: Record<string, number> = {};
  for (const [id, player] of Object.entries(playerDB)) {
    const name = player.full_name ?? `${player.first_name} ${player.last_name}`;
    const ref = REF_DATA[normalize(name)];
    if (ref !== undefined) {
      map[id] = ref;
    }
  }
  return map;
}
